//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_HIL_SENSOR_UPDATED_FLAGS(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.HIL_SENSOR_UPDATED_FLAGS
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.HIL_SENSOR_UPDATED_XACC.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.HIL_SENSOR_UPDATED_FLAGS
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.HIL_SENSOR_UPDATED_XACC, dec)
	})
}
